package com.intermarche.backoffice.engine.fieldops;
import com.intermarche.backoffice.domain.shipping.ParcelContent;import com.intermarche.backoffice.domain.store.Store;import com.intermarche.backoffice.domain.executing.PickedItem;import com.intermarche.backoffice.engine.operator.OperatorFailure;import java.util.*;import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
public final class ParcelContentGuard {private ParcelContentGuard(){}public static void requireUnchanged(Store store,Collection<Long> lineIds){if(lineIds.isEmpty())return;for(var c:ParcelContent.<ParcelContent>list("select c from ParcelContent c join fetch c.pickedItem i where c.parcel.store=?1 and c.parcel.state in ('CLOSED','LOADED') and i.lotLine.id in ?2",store,lineIds)){var i=c.pickedItem;if(i.status!=PickedItem.PickStatus.PICKED||(c.parcel.materialized?i.loadedTote!=null:i.loadedTote==null||!Objects.equals(c.sourceToteId,id(i.loadedTote)))||!Objects.equals(c.sourceProductId,id(i.product))||c.sourceQuantity.compareTo(i.quantity)!=0)throw new OperatorFailure(409,"PARCEL_CLOSED","Ces marchandises sont dans un colis fermé : faites rouvrir le colis avant de modifier leur contenu.");}}}
